class Solution:
    def isCompleteBT(self,root):
        from collections import deque
        q = deque([root])
        null_encountered = False
        while q:
            node = q.popleft()
            if node is None:
                null_encountered = True
            else:
                if null_encountered:
                    return False
                q.append(node.left)
                q.append(node.right)
        return True
